package t57

import (
	"testing"

	"github.com/DATASMARTCOMCORP/traccar-api-java/server-go/internal/ingest"
	"github.com/DATASMARTCOMCORP/traccar-api-java/server-go/internal/protocol/kit"
	"github.com/DATASMARTCOMCORP/traccar-api-java/server-go/internal/protocol/oracle"
)

func TestJavaDecoder(t *testing.T) {
	oracle.Run(t, "T57ProtocolDecoderTest", oracle.Handlers{
		Decoder: func(string, *oracle.Env) ingest.Decoder { return ingest.DecoderFunc(decode) },
	})
}

// TestFramer ports T57FrameDecoderTest (its calls are not recorded).
func TestFramer(t *testing.T) {
	const want = "2a5435372346312354353731313137303031233330313131372330303038343323323233342e31333033234e2330383832362e313731342345232b302e3234322c2b302e3130392c2d302e37383923302e30303023362e323030303023413223342e3223"
	const in = ""
	got := Framer().Frame(nil, kit.Hex(in))
	if b, ok := got.(*kit.Buf); !ok || b.HexDump() != want {
		t.Errorf("frame: got %v", got)
	}
}
